private void verifyDrawing() throws IOException {
    final int rectX = borderExtent.x;
    final int rectY = borderExtent.y;
    final int rectWidth = borderExtent.width;
    final int rectHeight = borderExtent.height;
    if (before.width > 0) {
        verify(graphicsPainter).moveTo(rectX, rectY);
        verify(graphicsPainter).lineTo(rectWidth, rectY);
        verify(graphicsPainter, times(numberOfNonZeroBorders(before, end))).lineTo(rectWidth - end.width, rectY + before.width);
        verify(graphicsPainter, times(numberOfNonZeroBorders(before, start))).lineTo(rectX + start.width, rectY + before.width);
    }
    if (end.width > 0) {
        verify(graphicsPainter).moveTo(rectWidth, rectY);
        verify(graphicsPainter).lineTo(rectWidth, rectHeight);
        verify(graphicsPainter, times(numberOfNonZeroBorders(end, after))).lineTo(rectWidth - end.width, rectHeight - after.width);
        verify(graphicsPainter, times(numberOfNonZeroBorders(end, before))).lineTo(rectWidth - end.width, rectY + before.width);
    }
    if (after.width > 0) {
        verify(graphicsPainter).moveTo(rectWidth, rectHeight);
        verify(graphicsPainter).lineTo(rectX, rectHeight);
        verify(graphicsPainter, times(numberOfNonZeroBorders(after, end))).lineTo(rectX + start.width, rectHeight - after.width);
        verify(graphicsPainter, times(numberOfNonZeroBorders(after, start))).lineTo(rectWidth - end.width, rectHeight - after.width);
    }
    if (start.width > 0) {
        verify(graphicsPainter).moveTo(rectX, rectHeight);
        verify(graphicsPainter).lineTo(rectX, rectY);
        verify(graphicsPainter, times(numberOfNonZeroBorders(start, before))).lineTo(rectX + start.width, rectY + before.width);
        verify(graphicsPainter, times(numberOfNonZeroBorders(start, after))).lineTo(rectX + start.width, rectHeight - after.width);
    }
    int numBorders = numberOfNonZeroBorders();
    verify(graphicsPainter, times(numBorders)).saveGraphicsState();
    verify(graphicsPainter, times(numBorders)).closePath();
    verify(graphicsPainter, times(numBorders)).restoreGraphicsState();
    verify(graphicsPainter, times(numBorders)).clip();
}

